#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypeScoreboardClient: FfiConverter {
    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = ScoreboardClient

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> ScoreboardClient {
        return ScoreboardClient(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: ScoreboardClient) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ScoreboardClient {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if ptr == nil {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: ScoreboardClient, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public func FfiConverterTypeScoreboardClient_lift(_ pointer: UnsafeMutableRawPointer) throws -> ScoreboardClient {
    return try FfiConverterTypeScoreboardClient.lift(pointer)
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public func FfiConverterTypeScoreboardClient_lower(_ value: ScoreboardClient) -> UnsafeMutableRawPointer {
    return FfiConverterTypeScoreboardClient.lower(value)
}

/**
 * One board's full server-side config, pushed with every BoardState.
 */
public struct UiBoardConfig {
    public var sports: [UiSportConfig]
    public var brightness: UInt8
    public var power: Bool
    public var extraGameIds: [String]
    /**
     * Preference-driven games one-off removed from the rotation.
     */
    public var excludedGameIds: [String]
    public var focusedGameId: String?
    public var name: String?
    public var offState: UiOffState
    public var sleepHours: UInt32
    /**
     * Seconds each game holds the panel before the rotation advances.
     */
    public var dwellSecs: UInt32
    /**
     * Unix seconds when a button-sleep auto-wakes (None when not sleeping).
     */
    public var wakeAt: UInt64?
    /**
     * Spoiler display: true = strict (matchup + time only), false = normal.
     */
    public var strictSpoilers: Bool
    /**
     * Spoiler-protect every game on this board.
     */
    public var spoilerAll: Bool
    /**
     * One-off spoiler-hidden games (cleared by Reset, pruned as games end).
     */
    public var spoilerGameIds: [String]
    /**
     * One-off revealed games (exceptions that beat every protection rule).
     */
    public var revealedGameIds: [String]
    /**
     * Board-local IANA timezone name ("America/New_York"); nil = server-local.
     */
    public var timezone: String?
    /**
     * Firmware release channel this board follows (`set_fw_channel`).
     */
    public var fwChannel: UiFwChannel
    /**
     * Serve this board a synthetic slate instead of live games. Only the
     * GAMES change — every other setting on the board is untouched.
     */
    public var demoData: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(sports: [UiSportConfig], brightness: UInt8, power: Bool, extraGameIds: [String],
                /**
                    * Preference-driven games one-off removed from the rotation.
                    */ excludedGameIds: [String], focusedGameId: String?, name: String?, offState: UiOffState, sleepHours: UInt32,
                /**
                    * Seconds each game holds the panel before the rotation advances.
                    */ dwellSecs: UInt32,
                /**
                    * Unix seconds when a button-sleep auto-wakes (None when not sleeping).
                    */ wakeAt: UInt64?,
                /**
                    * Spoiler display: true = strict (matchup + time only), false = normal.
                    */ strictSpoilers: Bool,
                /**
                    * Spoiler-protect every game on this board.
                    */ spoilerAll: Bool,
                /**
                    * One-off spoiler-hidden games (cleared by Reset, pruned as games end).
                    */ spoilerGameIds: [String],
                /**
                    * One-off revealed games (exceptions that beat every protection rule).
                    */ revealedGameIds: [String],
                /**
                    * Board-local IANA timezone name ("America/New_York"); nil = server-local.
                    */ timezone: String?,
                /**
                    * Firmware release channel this board follows (`set_fw_channel`).
                    */ fwChannel: UiFwChannel,
                /**
                    * Serve this board a synthetic slate instead of live games. Only the
                    * GAMES change — every other setting on the board is untouched.
                    */ demoData: Bool)
    {
        self.sports = sports
        self.brightness = brightness
        self.power = power
        self.extraGameIds = extraGameIds
        self.excludedGameIds = excludedGameIds
        self.focusedGameId = focusedGameId
        self.name = name
        self.offState = offState
        self.sleepHours = sleepHours
        self.dwellSecs = dwellSecs
        self.wakeAt = wakeAt
        self.strictSpoilers = strictSpoilers
        self.spoilerAll = spoilerAll
        self.spoilerGameIds = spoilerGameIds
        self.revealedGameIds = revealedGameIds
        self.timezone = timezone
        self.fwChannel = fwChannel
        self.demoData = demoData
    }
}

extension UiBoardConfig: Equatable, Hashable {
    public static func == (lhs: UiBoardConfig, rhs: UiBoardConfig) -> Bool {
        if lhs.sports != rhs.sports {
            return false
        }
        if lhs.brightness != rhs.brightness {
            return false
        }
        if lhs.power != rhs.power {
            return false
        }
        if lhs.extraGameIds != rhs.extraGameIds {
            return false
        }
        if lhs.excludedGameIds != rhs.excludedGameIds {
            return false
        }
        if lhs.focusedGameId != rhs.focusedGameId {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.offState != rhs.offState {
            return false
        }
        if lhs.sleepHours != rhs.sleepHours {
            return false
        }
        if lhs.dwellSecs != rhs.dwellSecs {
            return false
        }
        if lhs.wakeAt != rhs.wakeAt {
            return false
        }
        if lhs.strictSpoilers != rhs.strictSpoilers {
            return false
        }
        if lhs.spoilerAll != rhs.spoilerAll {
            return false
        }
        if lhs.spoilerGameIds != rhs.spoilerGameIds {
            return false
        }
        if lhs.revealedGameIds != rhs.revealedGameIds {
            return false
        }
        if lhs.timezone != rhs.timezone {
            return false
        }
        if lhs.fwChannel != rhs.fwChannel {
            return false
        }
        if lhs.demoData != rhs.demoData {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(sports)
        hasher.combine(brightness)
        hasher.combine(power)
        hasher.combine(extraGameIds)
        hasher.combine(excludedGameIds)
        hasher.combine(focusedGameId)
        hasher.combine(name)
        hasher.combine(offState)
        hasher.combine(sleepHours)
        hasher.combine(dwellSecs)
        hasher.combine(wakeAt)
        hasher.combine(strictSpoilers)
        hasher.combine(spoilerAll)
        hasher.combine(spoilerGameIds)
        hasher.combine(revealedGameIds)
        hasher.combine(timezone)
        hasher.combine(fwChannel)
        hasher.combine(demoData)
    }
}

