        }
        if lhs.altColor != rhs.altColor {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(name)
        hasher.combine(abbrev)
        hasher.combine(color)
        hasher.combine(altColor)
    }
}

